def restock_needed(items, threshold=5):
    """Return the names of items whose quantity is below the threshold, sorted."""
    return sorted(name for name, qty in items.items() if qty <= threshold)


def total_value(items, prices):
    """Total stock value: sum of quantity * price. Items with no price count as 0."""
    return sum(qty * prices[name] for name, qty in items.items())

