import unittest

from inventory import restock_needed, total_value


class RestockTests(unittest.TestCase):
    def test_only_items_below_the_threshold(self):
        self.assertEqual(restock_needed({"a": 5, "b": 4, "c": 9}), ["b"])

    def test_result_is_sorted(self):
        self.assertEqual(restock_needed({"z": 1, "m": 2}), ["m", "z"])


class ValueTests(unittest.TestCase):
    def test_total(self):
        self.assertEqual(total_value({"a": 2, "b": 3}, {"a": 1.5, "b": 2}), 9.0)

    def test_missing_price_counts_as_zero(self):
        self.assertEqual(total_value({"a": 2, "ghost": 7}, {"a": 1.5}), 3.0)


if __name__ == "__main__":
    unittest.main()

