import unittest

from inventory import restock_needed, total_value


class HiddenRestock(unittest.TestCase):
    def test_boundary_is_not_included(self):
        self.assertEqual(restock_needed({"x": 10, "y": 9}, threshold=10), ["y"])

    def test_default_threshold_is_five(self):
        self.assertEqual(restock_needed({"a": 5, "b": 6, "c": 0}), ["c"])

    def test_empty(self):
        self.assertEqual(restock_needed({}), [])


class HiddenValue(unittest.TestCase):
    def test_all_missing(self):
        self.assertEqual(total_value({"a": 3}, {}), 0)

    def test_zero_price_and_empty(self):
        self.assertEqual(total_value({"a": 3}, {"a": 0}), 0)
        self.assertEqual(total_value({}, {"a": 1}), 0)

    def test_mixed(self):
        self.assertEqual(total_value({"a": 1, "b": 2, "c": 3}, {"a": 10, "c": 1}), 13)


if __name__ == "__main__":
    unittest.main()
